"use client";

import { useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { Loader2 } from "lucide-react";
import { createClient } from "@/utils/supabase/client";

export default function LoginPage() {
  const supabase = createClient();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: `${window.location.origin}/auth/callback`
        }
      });
      if (error) throw error;
    } catch (err: any) {
      setError(err.message || "Authentication failed");
      setIsLoading(false);
    }
  };



  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-4 bg-muted/20 pb-12">
      <div className="w-full max-w-md">
        
        <h1 className="text-[22px] font-semibold text-center text-foreground mb-6">
          Login to your account
        </h1>
        
        <div className="bg-card border border-border px-6 py-8 sm:px-8 sm:py-10 rounded-xl shadow-sm w-full">
          
          <div className="flex justify-center mb-10">
            <Link href="/" className="relative w-40 h-40 sm:w-48 sm:h-48 rounded-xl overflow-hidden shadow-lg border border-border/50 hover:scale-105 transition-transform duration-300">
              <Image src="/logo.jpg" alt="Code With Abanoub Logo" fill className="object-cover" priority />
            </Link>
          </div>

          {error && (
            <div className="bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-900/50 text-red-600 dark:text-red-500 text-sm px-4 py-3 rounded-md mb-6">
              {error}
            </div>
          )}

          <div className="mb-8 text-center text-sm text-muted-foreground">
            To ensure secure access to your course materials, please sign in with your Google Account.
          </div>

          <button 
            type="button"
            onClick={handleGoogleLogin} 
            disabled={isLoading}
            className="w-full flex items-center justify-center gap-3 bg-background border border-border text-foreground font-medium py-3 px-4 rounded-md transition-colors hover:bg-muted/50 shadow-sm"
          >
            {isLoading ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <svg className="w-5 h-5" viewBox="0 0 24 24">
                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
              </svg>
            )}
            {isLoading ? "Redirecting..." : "Continue with Google"}
          </button>
          
        </div>

        <div className="mt-8 text-center text-[13px] text-muted-foreground/80">
          <p>By creating an account and logging into Code LMS you</p>
          <p>are agreeing to our <Link href="#" className="underline hover:text-muted-foreground transition-colors">terms of use</Link>.</p>
        </div>

      </div>
    </div>
  );
}
